facts:
If only a slant height $l$ is given for a cone, first find the perpendicular height with Pythagoras, $h = \sqrt{l^{2} - r^{2}}$, then substitute.

[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc}
\coordinate (O) at (0,0);
\coordinate (L) at (-1.6,0);
\coordinate (R) at (1.6,0);
\coordinate (T) at (0,3.4);
\draw (L) arc[start angle=180, end angle=360, x radius=1.6, y radius=0.5];
\draw[dashed] (L) arc[start angle=180, end angle=0, x radius=1.6, y radius=0.5];
\draw (T) -- (L);
\draw (T) -- (R) node[midway, right] {$l$};
\draw[dashed] (O) -- (T) node[midway, left] {$h$};
\draw (O) -- (R) node[midway, below] {$r$};
\fill (O) circle (1.2pt);
\coordinate (p) at ($(O)!0.25cm!(T)$);
\coordinate (q) at ($(O)!0.25cm!(R)$);
\draw (p) -- ($(p)+(q)-(O)$) -- (q);
\end{tikzpicture}
[/tikz]

